queries:
SELECT COUNT(*) AS total_completed
FROM orders
WHERE status = 'completed';

SELECT oi.order_id, oi.product_id, oi.quantity, oi.unit_price, oi.discount
FROM order_items oi
WHERE oi.order_id IN (3373, 3432, 3433, 3446, 3456, 3460, 3478, 3497, 3531, 3552, 3558, 3561, 3572, 3587, 3612, 3618, 3641);

SELECT COUNT(*) AS completed_orders
FROM orders
WHERE status = 'completed' AND order_date >= date('2025-12-01') AND order_date < date('2026-01-01');
